<?php require __DIR__.'/../bootstrap/app.php';$db=Database::get();$n=(int)$db->query("SELECT COUNT(*) FROM users u JOIN roles r ON r.id=u.role_id WHERE r.name='admin'")->fetchColumn();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'&&$n===0){verify_csrf();if(strlen($_POST['password'])<10)exit('Password must be at least 10 characters.');$rid=$db->query("SELECT id FROM roles WHERE name='admin'")->fetchColumn();$s=$db->prepare("INSERT INTO users(name,email,password_hash,role_id,status) VALUES(?,?,?,?, 'active')");$s->execute([trim($_POST['name']),strtolower(trim($_POST['email'])),password_hash($_POST['password'],PASSWORD_DEFAULT),$rid]);$msg='Admin created. Delete this setup file now.';$n=1;}?><!doctype html><html><head><meta charset="utf-8"><title>YEHA admin setup</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="container py-5"><h1>One-time admin setup</h1><p><?=e($msg)?></p><?php if(!$n):?><form method="post" class="col-md-6"><?=csrf_field()?><input class="form-control mb-2" name="name" placeholder="Name" required><input class="form-control mb-2" name="email" type="email" placeholder="Email" required><input class="form-control mb-2" name="password" type="password" minlength="10" placeholder="Password (10+ chars)" required><button class="btn btn-dark">Create admin</button></form><?php else:?><p>An administrator exists. Delete this file.</p><?php endif;?></body></html>